<script lang="ts">
  import { Stage } from '../lib/render/renderer';
  import { EMOJI_CELL, EMOJI_COLS, EMOJI_SHEETS, type EmojiName } from '../lib/emoji/sheets.gen';

  /** One animated Noto emoji, drawn with the same sprite renderer as the characters. */
  let { name, size }: { name: EmojiName; size: number } = $props();

  // Typed loosely on purpose: WXT's list of public paths is only regenerated by a build,
  // and a type check run before that must not fail on the emoji sheets.
  const assetUrl = (path: string) => (browser.runtime.getURL as (p: string) => string)(path);

  let host: HTMLDivElement;
  let stage: Stage | undefined;
  // "Reduce motion" in the OS: show the emoji's fullest frame, still.
  const still = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

  $effect(() => {
    stage = new Stage(host, { w: EMOJI_CELL, h: EMOJI_CELL });
    return () => stage?.destroy();
  });

  $effect(() => {
    const sheet = EMOJI_SHEETS[name];
    stage?.show(
      {
        kind: 'sprite',
        src: assetUrl(`/emoji/${name}.webp`),
        frames: sheet.frames,
        cols: EMOJI_COLS,
        fps: sheet.fps,
      },
      undefined,
      { still, frame: sheet.poster },
    );
  });
</script>

<div class="emoji" style:width="{size}px" style:height="{size}px">
  <div class="scaler" bind:this={host} style:transform="scale({size / EMOJI_CELL})"></div>
</div>

<style>
  .emoji {
    pointer-events: none;
    overflow: hidden;
  }
  .scaler {
    transform-origin: 0 0;
    width: max-content;
  }
</style>
